// init.js — fixed
async function init() {
    const scene = new THREE.Scene();
    // ... setup renderer, camera, lights, terrain
    try {
        await loadAssets();
        GameState.sceneReady = true;
        startRenderLoop();
    } catch (err) {
        console.error('init failed:', err);
        // show error on overlay so player isn't stuck staring at nothing
        const overlay = document.getElementById('start-overlay');
        overlay.innerHTML = '<h2>Load failed — check console</h2>';
    }
}
