I said: A dash. Yes — a deer bursting through underbrush at 2x speed for half a second. That's not just movement, that's *character*. Prey animal energy.

Here's what I'm thinking. We add it to `player.js` alongside the basic FPS controls:

```js
const DASH_SPEED = 18;
const DASH_DURATION = 0.25;
const DASH_COOLDOWN = 1.2;

export function createPlayer(camera) {
  const keys = {};
  let isDashing = false;
  let dashTime = 0;
  let cooldown = 0;

  window.addEventListener('keydown', (e) => {
    keys[e.code] = true;
    if (e.code === 'ShiftLeft' && cooldown <= 0) {
      isDashing = true;
      dashTime = DASH_DURATION;
    }
  });
  window.addEventListener('keyup', (e) => { keys[e.code] = false; });

  return {
    update(dt) {
      cooldown = Math.max(0, cooldown - dt);

      let speed = 5;
      if (isDashing) {
        speed = DASH_SPEED;
        dashTime -= dt;
        if (dashTime <= 0) { isDashing = false; cooldown = DASH_COOLDOWN; }
      }

      const forward = new THREE.Vector3();
      camera.getWorldDirection(forward);
      forward.y = 0; forward.normalize();
      const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0));

      const move = new THREE.Vector3();
      if (keys['KeyW']) move.add(forward);
      if (keys['KeyS']) move.sub(forward);
      if (keys['KeyD']) move.add(right);
      if (keys['KeyA']) move.sub(right);

      if (move.lengthSq() > 0) {
        move.normalize().multiplyScalar(speed * dt);
        camera.position.add(move);
      }
    }
  };
}
```

Shift to dash, 1.2s cooldown so you can't spam it. I know I'm allocating vectors in the update loop there — I'll swap those out for shared temp vectors once we wire everything together. Bad parrot, I know.

We could even add a subtle FOV kick on dash later. That lurch where the world widens for a split second — really sells the burst. Want me to drop in the environment next so we actually have trees to dash through?

